const $=id=>document.getElementById(id);
function mode(value){const route=value==='route';$('routeFields').hidden=!route;$('priorityField').hidden=!route;for(const [id,on] of [['nearTab',!route],['routeTab',route]]){$(id).classList.toggle('active',on);$(id).setAttribute('aria-selected',String(on));}$('searchText').textContent=route?'내 일정에 맞는 보관함 찾기':'가까운 보관함 찾기';$('modeTitle').textContent=route?'찾으러 갈 때까지, 편하게.':'일단, 짐부터 내려놓을까요?';$('modeDescription').textContent=route?'방문과 짐 회수 동선을 함께 비교해요.':'출발지에서 가까운 보관함을 비교해요.';}
$('nearTab').onclick=()=>mode('near');$('routeTab').onclick=()=>mode('route');
document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>document.querySelectorAll('[data-size]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));}));

$('sizeHelp').onclick=()=>{$('formError').textContent='검색 결과의 제공 규격을 확인해주세요. 시설마다 규격이 달라요.';};
$('compareButton').hidden=true;document.querySelector('.sort-row').hidden=true;
$('resultCaption').textContent='';$('cards').innerHTML='<div class="empty"><h3>보관함 정보를 준비하고 있어요</h3><p>지역과 출발지를 입력하고 검색해주세요.</p></div>';
const local=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);const now=new Date();$('deposit').value=local(now);$('pickup').value=local(new Date(now.getTime()+2*3600000));mode('near');

const regions=[['1150000000','서울 강서구'],['1111000000','서울 종로구'],['1114000000','서울 중구'],['1117000000','서울 용산구'],['1120000000','서울 성동구'],['1121500000','서울 광진구'],['1123000000','서울 동대문구'],['1126000000','서울 중랑구'],['1129000000','서울 성북구'],['1130500000','서울 강북구'],['1132000000','서울 도봉구'],['1135000000','서울 노원구'],['1138000000','서울 은평구'],['1141000000','서울 서대문구'],['1144000000','서울 마포구'],['1147000000','서울 양천구'],['1153000000','서울 구로구'],['1154500000','서울 금천구'],['1156000000','서울 영등포구'],['1159000000','서울 동작구'],['1162000000','서울 관악구'],['1165000000','서울 서초구'],['1168000000','서울 강남구'],['1171000000','서울 송파구'],['1174000000','서울 강동구']];
$('region').innerHTML=regions.map(([v,n])=>'<option value="'+v+'">'+n+'</option>').join('');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=s=>s?String(s).slice(0,2)+':'+String(s).slice(2,4):'미제공';
$('plannerForm').onsubmit=async e=>{e.preventDefault();const btn=document.querySelector('.search-button');if(btn.disabled)return;const q={code:$('region').value,start:$('start').value.trim(),visit:$('visit').value.trim(),end:$('end').value.trim(),mode:$('routeFields').hidden?'near':'route',size:document.querySelector('[data-size].active').dataset.size,priority:$('priority').value,deposit:$('deposit').value,pickup:$('pickup').value};if(!q.start||(q.mode==='route'&&(!q.visit||!q.end))){$('formError').textContent='출발지와 목적지를 입력해주세요.';return;}if(new Date(q.pickup)<=new Date(q.deposit)){$('formError').textContent='찾을 시각은 맡길 시각 이후로 선택해주세요.';return;}btn.disabled=true;const label=$('searchText').textContent;$('searchText').textContent='보관함과 경로 조회 중…';$('formError').textContent='';try{const r=await fetch('/api/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(q)});const d=await r.json();if(!r.ok)throw Error(d.error||'조회 실패');$('resultsTitle').textContent='보관함 '+d.results.length+'곳';$('mapPlaceholder').innerHTML='<h3>'+esc(d.start.name)+' 기준 검색</h3><p>'+esc(d.scope)+'</p>';$('summary').classList.add('visible');$('summary').textContent=d.note+' · '+d.source;$('cards').innerHTML=d.results.length?d.results.map(l=>'<article class="locker-card"><div class="card-title"><h3>'+esc(l.name)+'</h3><p>'+esc(l.address)+'<br>'+esc(l.location)+'</p></div><div class="metrics"><div class="metric"><small>전체 이동</small><strong>'+(l.total===null?'경로 없음':l.total+'분')+'</strong></div><div class="metric"><small>짐 동반 이동</small><strong>'+(l.carry===null?'확인 필요':l.carry+'분')+'</strong></div><div class="metric"><small>선택 크기 빈자리</small><strong>'+esc(l.available===null?'미제공':l.available+'칸')+'</strong></div></div><p class="subtle">집계 시각: '+esc(l.asOf||'미제공')+' · 도착 시 빈자리는 달라질 수 있어요.</p><p class="subtle">평일 '+clock(l.hours.weekday[0])+'–'+clock(l.hours.weekday[1])+' / 토요일 '+clock(l.hours.saturday[0])+'–'+clock(l.hours.saturday[1])+' / 공휴일 '+clock(l.hours.holiday[0])+'–'+clock(l.hours.holiday[1])+'</p>'+ (l.details.length?l.details.map(x=>'<p>'+esc(x.stlckKndNm)+' · '+esc(x.utztnCrgExpln||'요금 미제공')+'<br>'+esc(x.addCrgExpln||'')+'<br>가로 '+esc(x.stlckWdthLenExpln||'?')+' / 높이 '+esc(x.stlckHgtExpln||'?')+' / 깊이 '+esc(x.stlckDpthExpln||'?')+'</p>').join(''):'<p>선택 크기의 규격·요금 미제공</p>')+'<details><summary>이동 구간 보기</summary>'+l.legs.map((leg,i)=>'<p>'+['출발 → 보관함','보관함 → 방문지','방문지 → 보관함','보관함 → 최종 목적지'][i]+': '+(leg?leg.minutes+'분<br>'+leg.steps.map(esc).join('<br>'):'경로 조회 불가')+'</p>').join('')+'</details></article>').join(''):'<div class="empty"><h3>이 지역에서 제공된 보관함이 없어요</h3><p>공공데이터 제공 범위에 따라 일부 시설은 조회되지 않을 수 있어요.</p></div>';}catch(err){$('formError').textContent=err.message;$('cards').innerHTML='<div class="empty"><h3>검색을 완료하지 못했어요</h3><p>설정 또는 외부 서비스 상태를 확인하고 다시 시도해주세요.</p></div>';}finally{btn.disabled=false;$('searchText').textContent=label;}};
